<script>
import { enhance } from '$app/forms';
  export let data;
  export let form;

$: upcoming = data.upcoming || [];
$: past = data.past || [];
$: errors = form?.errors || {};
$: values = form?.values || {};

  let showForm = false;
  let showPast = false;
  let submitting = false;

function todayISO() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

  function formatDate(dateStr) {
    const d = new Date(dateStr);
    return d.toLocaleDateString('de-DE', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
  }

    function daysUntil(dateStr) {
      const d = new Date(dateStr);
      d.setHours(0,0,0,0);
      const now = new Date();
      now.setHours(0,0,0,0);
      return Math.round((d - now) / (1000 * 60 * 60 * 24));
    }

      function urgencyClass(days) {
        if (days <= 3) return 'exam-urgent';
        if (days <= 7) return 'exam-soon';
            return 'exam-ok';
      }

        $: if (form?.errors) showForm = true;
        </script>

        <svelte:head>
          <title>Prüfungstermine – StudyStreak</title>
        </svelte:head>

        <div class="page-content">
            <div class="page-header-row">
                  <a href="/" class="btn btn-ghost" style="padding-left:0">← Zurück</a>
                        <h1>Prüfungstermine</h1>
                    <button class="btn btn-primary btn-sm" on:click={() => showForm = !showForm}>
                      {showForm ? '✕ Schliessen' : '+ Neu'}
                          </button>
                        </div>

                      {#if errors._form}
                        <div class="alert alert-error">{errors._form}</div>
                          {/if}

                          {#if showForm}
                                <div class="exam-form-card">
                                        <h3 style="margin-bottom:1rem">Neuer Prüfungstermin</h3>
                                  <form method="POST" action="?/create" use:enhance={() => {
                                            submitting = true;
                                    return async ({ update }) => { await update(); submitting = false; };
                                  }}>
                                          <div class="form-group">
                                                      <label class="form-label" for="subject">Fach / Modul *</label>
                                                                  <input
                                                                    id="subject"
                                                                    name="subject"
                                                                    type="text"
                                                                    class="form-input"
                                                                                  placeholder="z.B. Mathematik, Englisch"
                                                                      value={values.subject || ''}
                                                                                  required
                                                                                />
                                                                      {#if errors.subject}<span class="form-error">{errors.subject}</span>{/if}
                                                                                </div>

                                                                                <div class="form-group">
                                                                                            <label class="form-label" for="examDate">Prüfungsdatum *</label>
                                                                                                        <input
                                                                                                          id="examDate"
                                                                                                          name="examDate"
                                                                                                          type="date"
                                                                                                          class="form-input"
                                                                                                            value={values.examDate || ''}
                                                                                                            min={todayISO()}
                                                                                                                        required
                                                                                                                      />
                                                                                                            {#if errors.examDate}<span class="form-error">{errors.examDate}</span>{/if}
                                                                                                                      </div>
                                                                                                              
                                                                                                                      <div class="form-group">
                                                                                                                                  <label class="form-label" for="location">Ort / Raum</label>
                                                                                                                                              <input
                                                                                                                                                id="location"
                                                                                                                                                name="location"
                                                                                                                                                type="text"
                                                                                                                                                class="form-input"
                                                                                                                                                              placeholder="z.B. Raum 204, Online"
                                                                                                                                                  value={values.location || ''}
                                                                                                                                                            />
                                                                                                                                                          </div>
                                                                                                                                                  
                                                                                                                                                          <div class="form-group">
                                                                                                                                                                      <label class="form-label" for="notes">Bemerkungen</label>
                                                                                                                                                                                  <textarea
                                                                                                                                                                                    id="notes"
                                                                                                                                                                                    name="notes"
                                                                                                                                                                                    class="form-input"
                                                                                                                                                                                                  rows="3"
                                                                                                                                                                                                  placeholder="z.B. Erlaubte Hilfsmittel, wichtige Themen, Tipps..."
                                                                                                                                                                                      >{values.notes || ''}</textarea>
                                                                                                                                                                                              </div>
                                                                                                                                                                                      
                                                                                                                                                                                              <div style="display:flex;gap:0.75rem;margin-top:1rem">
                                                                                                                                                                                                <button type="submit" class="btn btn-primary" disabled={submitting}>
                                                                                                                                                                                                              {submitting ? 'Speichern...' : 'Termin speichern'}
                                                                                                                                                                                                            </button>
                                                                                                                                                                                                            <button type="button" class="btn btn-ghost" on:click={() => showForm = false}>Abbrechen</button>
                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                    </form>
                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                {/if}
                                                                                                                                                                                                                  
                                                                                                                                                                                                                    <!-- Upcoming exams -->
                                                                                                                                                                                                                    <h2 class="section-title">Kommende Prüfungen ({upcoming.length})</h2>
                                                                                                                                                                                                                      
                                                                                                                                                                                                                        {#if upcoming.length === 0}
                                                                                                                                                                                                                              <div class="card text-center text-muted exam-empty">
                                                                                                                                                                                                                                      <div style="font-size:2rem;margin-bottom:0.5rem">🎓</div>
                                                                                                                                                                                                                                      <p>Keine anstehenden Prüfungen.</p>
                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                  {:else}
                                                                                                                                                                                                                                        <div class="exam-list">
                                                                                                                                                                                                                                                {#each upcoming as exam (exam._id)}
                                                                                                                                                                                                                                                  {@const days = daysUntil(exam.examDate)}
                                                                                                                                                                                                                                                  <div class="exam-card {urgencyClass(days)}">
                                                                                                                                                                                                                                                              <div class="exam-card-top">
                                                                                                                                                                                                                                                                            <div class="exam-subject">{exam.subject}</div>
                                                                                                                                                                                                                                                                                          <div class="exam-days-badge">
                                                                                                                                                                                                                                                                                                          {#if days === 0}
                                                                                                                                                                                                                                                                                                                            <span class="badge badge-danger">Heute!</span>
                                                                                                                                                                                                                                                                                                                                            {:else if days === 1}
                                                                                                                                                                                                                                                                                                                                                              <span class="badge badge-warning">Morgen</span>
                                                                                                                                                                                                                                                                                                                                                                              {:else}
                                                                                                                                                                                                                                                                                                                                                                                                <span class="badge">in {days} Tagen</span>
                                                                                                                                                                                                                                                                                                                                                                                                                {/if}
                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="exam-date">📅 {formatDate(exam.examDate)}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                        {#if exam.location}
                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="exam-detail">📍 {exam.location}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {/if}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {#if exam.notes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="exam-notes">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="exam-notes-label">📝 Bemerkungen</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="exam-notes-text">{exam.notes}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {/if}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <form method="POST" action="?/delete" use:enhance style="margin-top:0.75rem">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <input type="hidden" name="id" value={exam._id} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button type="submit" class="btn btn-ghost btn-xs exam-delete-btn"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onclick="return confirm('Prüfungstermin wirklich löschen?')">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      🗑 Löschen
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {/each}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {/if}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <!-- Past exams (collapsible) -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {#if past.length > 0}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button class="past-toggle" on:click={() => showPast = !showPast}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {showPast ? '▲' : '▼'} Vergangene Prüfungen ({past.length})
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {#if showPast}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div class="exam-list exam-list-past">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {#each past as exam (exam._id)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="exam-card exam-past">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="exam-card-top">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="exam-subject">{exam.subject}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span class="badge badge-muted">Vorbei</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div class="exam-date">📅 {formatDate(exam.examDate)}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {#if exam.location}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="exam-detail">📍 {exam.location}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/if}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {#if exam.notes}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="exam-notes">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="exam-notes-label">📝 Bemerkungen</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="exam-notes-text">{exam.notes}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/if}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <form method="POST" action="?/delete" use:enhance style="margin-top:0.75rem">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <input type="hidden" name="id" value={exam._id} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button type="submit" class="btn btn-ghost btn-xs exam-delete-btn"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onclick="return confirm('Prüfungstermin wirklich löschen?')">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        🗑 Löschen
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {/each}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/if}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {/if}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <style>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .page-header-row {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          justify-content: space-between;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          margin-bottom: 1rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .page-header-row h1 { margin: 0; font-size: 1.25rem; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .btn-sm { font-size: 0.85rem; padding: 0.35rem 0.75rem; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .btn-xs { font-size: 0.78rem; padding: 0.2rem 0.6rem; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-form-card {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          background: var(--c-surface);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border: 1px solid var(--c-border);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border-radius: var(--radius-md);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          padding: 1.25rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          margin-bottom: 1.5rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          box-shadow: var(--shadow-sm);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .section-title {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          font-size: 0.95rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          font-weight: 700;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color: var(--c-text-muted);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          text-transform: uppercase;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          letter-spacing: 0.06em;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          margin: 1.25rem 0 0.75rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-list { display: flex; flex-direction: column; gap: 0.75rem; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-list-past { opacity: 0.75; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-card {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          background: var(--c-surface);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border-radius: var(--radius-md);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          padding: 1rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border-left: 4px solid var(--c-border);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          box-shadow: var(--shadow-sm);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-urgent { border-left-color: var(--c-danger); background: #fff8f8; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-soon   { border-left-color: var(--c-warning); background: #fffdf0; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-ok     { border-left-color: var(--c-success); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-past   { border-left-color: var(--c-border-strong); filter: grayscale(0.3); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-card-top {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          justify-content: space-between;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          margin-bottom: 0.35rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-subject { font-weight: 700; font-size: 1rem; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-date, .exam-detail { font-size: 0.88rem; color: var(--c-text-muted); margin-top: 0.15rem; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-notes {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          margin-top: 0.6rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          background: var(--c-bg);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border-radius: var(--radius-sm);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          padding: 0.6rem 0.75rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-notes-label { font-size: 0.78rem; font-weight: 600; color: var(--c-text-muted); margin-bottom: 0.25rem; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .exam-notes-text { font-size: 0.88rem; white-space: pre-wrap; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .badge {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          display: inline-block;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          font-size: 0.75rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          font-weight: 700;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          padding: 0.15rem 0.55rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border-radius: var(--radius-pill);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          background: var(--c-primary-light);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color: var(--c-primary);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .badge-danger  { background: var(--c-danger-light); color: var(--c-danger); }
